Definition shadow_bytes (m : word -> option byte) (s1 s2 : Z) (f : Z -> Z) : Prop :=
  0 <= s1 /\ s2 <= 2^64 /\ forall s, s1 <= s < s2 -> m (wa s) = Some (Z_to_bv 8 (f s)).

