Definition no_image (s1 s2 : Z) : Prop := forall z, s1 <= z < s2 -> find_segment segs z 1 = None.

Lemma mrd_no_image : forall m s1 s2 s, no_image s1 s2 -> s1 <= s < s2 -> 0 <= s1 -> s2 <= 2^64 ->
