Definition unpoisoned (m : word -> option byte) (lo hi : Z) : Prop :=
  0 <= lo /\ hi <= 2^64 /\
  forall G, lo < hi -> lo <= 8 * G + 7 -> 8 * G < hi ->
    exists b, m (wa (ASHOFF + G)) = Some b /\ gran_ok (Z.min (8 * G + 8) hi - 8 * G) b.

