Definition shadow_block (m : word -> option byte) (p n : Z) : Prop :=
  p mod 8 = 0 /\ 0 <= p /\ 0 <= n /\ p + n <= 2^64 /\ shadow_bytes m (shad p) (shad p + nshad n) (blockf p n).

