Lemma shadow_block_intro_full : forall m p n f,
  p mod 8 = 0 -> 0 <= p -> 0 <= n -> p + n <= 2^64 -> n mod 8 = 0 ->
  shadow_bytes m (shad p) (shad p + n / 8) f -> (forall s, shad p <= s < shad p + n / 8 -> (f s) mod 256 = 0) ->
